inset.css:
background: color-mix(in srgb, var(--card) 95%, var(--accent) 5%);
box-shadow:
inset 2px 2px 4px color-mix(in srgb, var(--foreground) 8%, transparent),
inset -2px -2px 4px color-mix(in srgb, var(--background) 20%, transparent);

glass-elevated.css:
backdrop-filter: blur(8px);
background: linear-gradient(to bottom right, color-mix(in srgb, var(--card) 80%, transparent), color-mix(in srgb, var(--card) 40%, transparent));
box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
border: 1px solid var(--card);

glass-depth.css:
background: color-mix(in srgb, var(--card) 80%, transparent);
backdrop-filter: blur(14px);
box-shadow:
inset 0 0 20px 0 color-mix(in srgb, var(--accent) 7.5%, transparent);
border: 1px solid var(--border);

gradient-bordered.css:
background: linear-gradient(180deg, color-mix(in srgb, var(--card) 100%, var(--accent) 5%) -35%, var(--card) 65%);
box-shadow: 0px 0px 10px 4px color-mix(in srgb, var(--accent) 4%, transparent);
border: 1px solid var(--border);

layered-gradient.css:
background:
linear-gradient(color-mix(in srgb, var(--accent) 6%, transparent) 0%, transparent 59.26%),
linear-gradient(var(--card) 0%, var(--card) 100%),
var(--card);
box-shadow:
20px 18px 7px color-mix(in srgb, var(--accent) 0%, transparent),
2px 2px 2px color-mix(in srgb, var(--accent) 6.5%, transparent),
1px 1px 2px color-mix(in srgb, var(--accent) 2%, transparent);
border: 2px solid var(--secondary);

elevated-border.css:
background: linear-gradient(180deg, color-mix(in srgb, var(--card) 100%, var(--foreground) 3%) 0%, var(--card) 100%);
box-shadow: 0 1px 0 0 color-mix(in srgb, var(--foreground) 8%, transparent), 0 4px 6px -1px color-mix(in srgb, var(--foreground) 5%, transparent), 0 10px 15px -3px color-mix(in srgb, var(--foreground) 4%, transparent);
border: 1px solid color-mix(in srgb, var(--foreground) 6%, transparent);

spotlight.css:
background:
radial-gradient(ellipse at 0% 0%, color-mix(in srgb, var(--accent) 20%, transparent) 0%, transparent 50%),
var(--card);
box-shadow: inset 1px 1px 0 0 color-mix(in srgb, var(--foreground) 10%, transparent), 0 4px 16px -4px color-mix(in srgb, var(--foreground) 10%, transparent);

radial-glow.css:
background:
radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--background) 32.5%, transparent) 0%, transparent 45%),
radial-gradient(circle at 100% 100%, color-mix(in srgb, var(--background) 32.5%, transparent) 0%, transparent 45%),
var(--primary);
box-shadow: 2.10837px 3.16256px 9.48767px color-mix(in srgb, var(--accent) 30%, transparent);

inset-glow.css:
background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 65%, var(--background)) -35%, var(--primary) 65%);
box-shadow: 0 10px 18px -7px color-mix(in srgb, var(--background) 50%, transparent), inset 0 1px 0 0 color-mix(in srgb, var(--foreground) 15%, transparent);
border: 1px solid color-mix(in srgb, var(--foreground) 20%, transparent);

glass.css:
backdrop-filter: blur(8px);
background: linear-gradient(to bottom right, color-mix(in srgb, var(--secondary) 80%, transparent), var(--secondary));
box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
border: 1px solid var(--secondary);

layered.css:
background:
linear-gradient(color-mix(in srgb, var(--accent) 5%, transparent) 0%, transparent 59.26%),
linear-gradient(var(--secondary), var(--secondary)),
linear-gradient(var(--secondary), var(--secondary)),
linear-gradient(color-mix(in srgb, var(--accent) 5%, transparent) 0%, transparent 59.26%),
linear-gradient(color-mix(in srgb, var(--secondary) 60%, transparent), color-mix(in srgb, var(--secondary) 60%, transparent)),
var(--secondary);
box-shadow:
2.10837px 3.16256px 9.48767px color-mix(in srgb, var(--accent) 10%, transparent);
border: 1px solid var(--secondary);

radial-glow.css:
background:
radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--accent) 15%, transparent) 0%, transparent 40%),
radial-gradient(circle at 100% 100%, color-mix(in srgb, var(--accent) 15%, transparent) 0%, transparent 40%),
var(--secondary);
box-shadow: 2.10837px 3.16256px 9.48767px color-mix(in srgb, var(--accent) 10%, transparent);
